// TLS 1.3 handshake test: Node server and client in one process under the
// gofips-only config (OpenSSL 4.0.3), so every handshake
// operation (ECDH/ECDSA P-256, SHA-256/384, HMAC, HKDF, AES-256-GCM, RAND)
// comes from gofips or fails.
//
// Gates:
//   1. TLS 1.3 handshake; logs protocol, cipher and key type.
//   2. Application data in both directions.
//   3. 5 serial and 20 parallel handshakes with traffic.
//   4. A ChaCha20-only client fails; a TLS 1.2 client connects with
//      AES-GCM, and a TLS 1.2 CBC-only client fails.
//   5. Session tickets are issued and a session resumes (PSK binder).
// The runner's C stage reads the per-op provider counters afterwards.

const tls = require('node:tls');
// Node derives its default session-id context with SHA-1, which gofips
// serves only as non-approved. Use a SHA-256-derived one instead.
const SESSION_ID_CONTEXT = require('node:crypto').createHash('sha256').update('gofips-session-context').digest('hex').slice(0, 32);
const { execFileSync } = require('node:child_process');
const fs = require('node:fs');
const assert = require('node:assert');

let fails = 0;
function check(cond, label) {
  console.log((cond ? 'PASS: ' : 'FAIL: ') + label);
  if (!cond) fails++;
}

// --- load the P-256 ECDSA test cert/key (generated by the runner) ---
const KEY = fs.readFileSync((process.env.GOFIPS_CERT_DIR || '/tmp/gofips') + '/tls-key.pem');
const CERT = fs.readFileSync((process.env.GOFIPS_CERT_DIR || '/tmp/gofips') + '/tls-cert.pem');

console.log('node:', process.version, 'openssl:', process.versions.openssl);
console.log('step: loading certs');

// --- single handshake, full negotiation details ---
function handshakeOnce(port, opts = {}) {
  return new Promise((resolve, reject) => {
    const socket = tls.connect({
      host: '127.0.0.1',
      port,
      rejectUnauthorized: false,
      minVersion: 'TLSv1.3',
      maxVersion: 'TLSv1.3',
      ...opts,
    }, () => {
      const proto = socket.getProtocol();
      const cipher = socket.getCipher();
      const eph = socket.getEphemeralKeyInfo();
      const peer = socket.getPeerCertificate(true);
      resolve({ socket, proto, cipher, eph, peer });
    });
    socket.on('error', reject);
  });
}

async function main() {
  console.log('step: creating server');
  console.log('step: creating server');
  // --- server ---
  const server = tls.createServer({
    key: KEY,
    cert: CERT,
    sessionIdContext: SESSION_ID_CONTEXT,
    minVersion: 'TLSv1.2',
    maxVersion: 'TLSv1.3',
  }, (sock) => {
    // application traffic: echo server
    sock.on('data', (d) => sock.write(Buffer.from(d).toString('hex')));
  });
  await new Promise((r) => server.listen(0, '127.0.0.1', r));
  console.log('step: server listening on', server.address().port);
  console.log('step: server listening on', server.address().port);
  const port = server.address().port;

  try {
    // --- Gate 1: single handshake, full details ---
    const h = await handshakeOnce(port);
    check(h.proto === 'TLSv1.3', `negotiated protocol is TLSv1.3 (got ${h.proto})`);
    // Node reports the IANA ciphersuite name (TLS_AES_256_GCM_SHA384);
    // the OpenSSL-name variant (AES256-GCM-SHA384) appears in some builds.
    check(!!h.cipher && /AES.*(GCM|256|128)/i.test(h.cipher.name),
          `negotiated cipher is AES-GCM via gofips (got ${h.cipher && h.cipher.name})`);
    const group = h.eph && (h.eph.name || h.eph.group);
    check(!!group && /prime256v1|P-256|secp256r1/i.test(String(group)),
          `key exchange group is P-256 (got ${group})`);
    const sig = h.peer && (h.peer.sigalg
      || (h.peer.issuerCertificate && h.peer.issuerCertificate.sigalg));
    // getPeerCertificate(true) may lack sigalg and pubKey.type. Accept an
    // ECDSA sigalg, nistCurve/asn1Curve, or the id-ecPublicKey OID
    // (1.2.840.10045.2.1) in the raw DER.
    const rawHex = h.peer && h.peer.raw ? h.peer.raw.toString('hex') : '';
    const ecOid = '06072a8648ce3d02'; // id-ecPublicKey prefix in SubjectPublicKeyInfo
    check(/ecdsa|ECDSA/i.test(String(sig))
      || !!(h.peer && (h.peer.nistCurve || h.peer.asn1Curve))
      || rawHex.includes(ecOid),
      `certificate signature/key is ECDSA (sig=${sig}, nistCurve=${h.peer && h.peer.nistCurve})`);

    // --- Gate 2: application data both directions ---
    const roundtrip = await new Promise((resolve, reject) => {
      let resp = '';
      const t = setTimeout(() => reject(new Error('echo timeout')), 5000);
      h.socket.on('data', (d) => { resp += d.toString(); if (resp.length >= 20) { clearTimeout(t); resolve(resp); } });
      h.socket.on('error', (e) => { clearTimeout(t); reject(e); });
      h.socket.write('hello-from-client-0001');
    });
    check(roundtrip.includes(Buffer.from('hello-from-client-0001').toString('hex')),
          'application data client->server->client roundtrip ok');
    // second exchange: server -> client
    const pushOk = await new Promise((resolve) => {
      server.emit('test-push', h.socket);
      let got = false;
      const t = setTimeout(() => resolve(got), 2000);
      h.socket.once('data', () => { got = true; clearTimeout(t); resolve(true); });
      h.socket.write('push-check');
    });
    check(pushOk, 'server->client application data ok');
    h.socket.end();

    // --- Gate 3: serial and parallel handshakes ---
    // 3a. serial: 5 sequential handshakes with traffic
    for (let i = 0; i < 5; i++) {
      const sh = await handshakeOnce(port);
      const msg = `serial-${i}-` + 'x'.repeat(64);
      const echo = await new Promise((resolve, reject) => {
        let resp = '';
        const t = setTimeout(() => reject(new Error('echo timeout')), 5000);
        sh.socket.on('data', (d) => { resp += d.toString(); if (resp.length >= msg.length * 2) { clearTimeout(t); resolve(resp); } });
        sh.socket.on('error', reject);
        sh.socket.write(msg);
      });
      check(echo.includes(Buffer.from(msg).toString('hex')), `serial handshake ${i + 1}/5 with 64B traffic ok`);
      sh.socket.end();
    }
    // 3b. parallel: 20 simultaneous handshakes with interleaved traffic
    const N = 20;
    const results = await Promise.all(Array.from({ length: N }, (_, i) =>
      new Promise((resolve, reject) => {
        const s = tls.connect({ host: '127.0.0.1', port, rejectUnauthorized: false,
                                minVersion: 'TLSv1.3', maxVersion: 'TLSv1.3' }, () => {
          const msg = `par-${i}-` + 'y'.repeat(128);
          let resp = '';
          const t = setTimeout(() => { s.destroy(); reject(new Error('par echo timeout')); }, 8000);
          s.on('data', (d) => {
            resp += d.toString();
            if (resp.length >= msg.length * 2) { clearTimeout(t); s.end(); resolve(resp); }
          });
          s.on('error', (e) => { clearTimeout(t); reject(e); });
          s.write(msg);
        });
        s.on('error', reject);
      })));
    const parOk = results.filter((r) => r && r.length > 0).length;
    check(parOk === N, `parallel handshakes ${parOk}/${N} all completed with traffic`);

    // --- Gate 4: fail-closed on unsupported algorithms ---
    // gofips has no ChaCha20, so a ChaCha20-only client must fail.
    const chachaFailed = await new Promise((resolve) => {
      const s = tls.connect({
        host: '127.0.0.1', port, rejectUnauthorized: false,
        minVersion: 'TLSv1.3', maxVersion: 'TLSv1.3',
        ciphers: 'TLS_CHACHA20_POLY1305_SHA256',
      });
      s.on('connect', () => { /* waiting */ });
      s.on('error', () => resolve(true));  // handshake failed = fail-closed
      s.on('secureConnect', () => { s.destroy(); resolve(false); });
      setTimeout(() => { s.destroy(); resolve(true); }, 4000); // timeout = fail-closed
    });
    check(chachaFailed, 'fail-closed: ChaCha20-only client handshake rejected/timeout (no silent fallback)');

    // TLS 1.2: AES-GCM suites with the extended master secret connect;
    // CBC suites do not.
    const t12 = await handshakeOnce(port, { minVersion: 'TLSv1.2', maxVersion: 'TLSv1.2' }).catch(() => null);
    check(!!t12 && t12.proto === 'TLSv1.2' && /GCM/.test(t12.cipher && t12.cipher.name),
          `TLS 1.2 handshake with AES-GCM (got ${t12 && t12.proto} ${t12 && t12.cipher && t12.cipher.name})`);
    if (t12) t12.socket.destroy();
    const cbcFailed = await new Promise((resolve) => {
      const s = tls.connect({
        host: '127.0.0.1', port, rejectUnauthorized: false,
        minVersion: 'TLSv1.2', maxVersion: 'TLSv1.2', ciphers: 'ECDHE-ECDSA-AES128-SHA256:ECDHE-ECDSA-AES256-SHA384',
      });
      s.on('error', () => resolve(true));
      s.on('secureConnect', () => { s.write('x'); s.once('data', () => { s.destroy(); resolve(false); }); });
      setTimeout(() => { s.destroy(); resolve(true); }, 4000);
    });
    check(cbcFailed, 'fail-closed: a TLS 1.2 CBC-only client carries no data');

    // --- Gate 5: session tickets and resumption ---
    let session;
    const first = await new Promise((resolve) => {
      const s = tls.connect({ host: '127.0.0.1', port, rejectUnauthorized: false,
                              minVersion: 'TLSv1.3', maxVersion: 'TLSv1.3' });
      const t = setTimeout(() => { s.destroy(); resolve(s); }, 5000);
      s.on('session', (sess) => { session = sess; });
      s.on('data', () => { clearTimeout(t); s.destroy(); resolve(s); });
      s.on('error', () => { clearTimeout(t); resolve(s); });
      s.on('secureConnect', () => s.write('ticket'));
    });
    check(!!session && !first.isSessionReused(), 'server issued a TLS 1.3 session ticket');
    if (session) {
      const resumed = await Promise.race([handshakeOnce(port, { session }),
        new Promise((r) => setTimeout(() => r(null), 5000))]).catch(() => null);
      check(!!resumed && resumed.socket.isSessionReused(), 'TLS 1.3 session resumed with the ticket (PSK binder through gofips HMAC)');
      if (resumed) resumed.socket.destroy();
    }
  } finally {
    server.close();
    await new Promise((r) => server.close(r));
  }

  console.log(fails === 0 ? 'TLS HANDSHAKE GATES PASSED' : 'TLS HANDSHAKE GATES FAILED');
  process.exit(fails === 0 ? 0 : 1);
}

main().catch((e) => { console.log('FATAL:', e.message); process.exit(1); });
